#pragma once
#include "shortcut_model.h"
#include "ui/message.h"
namespace moon::shortcuts {
inline std::string keyboardKey(const ui::KeyMessage& key){const auto code=key.scancode();if(code>=ui::kKeyA&&code<=ui::kKeyZ)return std::string(1,char('A'+code-ui::kKeyA));if(code>=ui::kKey0&&code<=ui::kKey9)return std::string(1,char('0'+code-ui::kKey0));if(code>=ui::kKeyF1&&code<=ui::kKeyF12)return "F"+std::to_string(code-ui::kKeyF1+1);switch(code){case ui::kKeyEsc:return "Escape";case ui::kKeySpace:return "Space";case ui::kKeyTab:return "Tab";case ui::kKeyEnter:return "Enter";case ui::kKeyBackspace:return "Backspace";case ui::kKeyDel:return "Delete";case ui::kKeyLeft:return "ArrowLeft";case ui::kKeyRight:return "ArrowRight";case ui::kKeyUp:return "ArrowUp";case ui::kKeyDown:return "ArrowDown";case ui::kKeyHome:return "Home";case ui::kKeyEnd:return "End";case ui::kKeyQuote:return "'";case ui::kKeyOpenbrace:return "[";case ui::kKeyClosebrace:return "]";case ui::kKeyComma:return ",";case ui::kKeyStop:return ".";default:break;}const auto value=key.unicodeChar();if(value>=33&&value<=126)return std::string(1,char(value));return {};}
inline std::string keyboardText(const ui::KeyMessage& key){std::string out;auto add=[&](const std::string& v){if(!out.empty())out+='+';out+=v;};if(key.ctrlPressed())add("Ctrl");if(key.altPressed())add("Alt");if(key.shiftPressed())add("Shift");if(key.cmdPressed())add("Win");const auto ordinary=keyboardKey(key);if(!ordinary.empty())add(ordinary);return normalize(out);}
inline bool keyboardBinding(const std::string& binding){const auto text=normalize(binding);if(text.empty()||text=="Ctrl"||text=="Alt"||text=="Shift"||text=="Space"||text=="Win")return false;if(text.find("Mouse")!=std::string::npos||text.find("Wheel")!=std::string::npos||text.find("Win")!=std::string::npos||text.find("Space+")!=std::string::npos)return false;const auto last=text.find_last_of('+');const auto key=last==std::string::npos?text:text.substr(last+1);return key!="Ctrl"&&key!="Alt"&&key!="Shift"&&key!="Space"&&key!="Win"&&key!="Escape";}

inline std::string eventText(const ui::Message& event,const std::string& key,bool space=false){std::string out;auto add=[&](const std::string& part){if(!out.empty())out+='+';out+=part;};if(event.ctrlPressed())add("Ctrl");if(event.altPressed())add("Alt");if(event.shiftPressed())add("Shift");if(event.cmdPressed())add("Win");if(space&&key!="Space")add("Space");add(key);return normalize(out);}
inline std::string mouseKey(const ui::MouseMessage& event){if(event.left())return "MouseLeft";if(event.right())return "MouseRight";if(event.middle())return "MouseMiddle";if(event.button()==ui::kButtonX1)return "MouseBack";if(event.button()==ui::kButtonX2)return "MouseForward";return {};}
inline std::string pointerText(const ui::MouseMessage& event,bool doubleClick=false,bool wheel=false,bool space=false){const auto key=wheel?(event.wheelDelta().y<0?"WheelUp":event.wheelDelta().y>0?"WheelDown":""):doubleClick&&event.left()?"MouseDoubleLeft":mouseKey(event);return key.empty()?std::string{}:eventText(event,key,space);}
}
